test('website page and ordered component references are structurally valid',()=>{assert.deepEqual(validateStudioState(seedState),[]);assert.deepEqual(orderedInstances(seedState).map(item=>item.id),['instance-hero','instance-services','instance-cta'])});
test('registry resolves definitions independently from instance content',()=>{const registry=createComponentRegistry().register({type:'example',contentSchema:['title'],render:content=>content.title});assert.equal(registry.resolve('example').render({title:'Reusable content'}),'Reusable content');assert.throws(()=>registry.resolve('missing'),/Unknown component type/)});
test('split Hero decorative art does not leak internal placeholder text',()=>{const original=globalThis.document;class Element{constructor(tag){this.tagName=tag;this.children=[];this.dataset={};this.attributes={};this.textContent='';this.className='';}append(...children){this.children.push(...children);}setAttribute(key,value){this.attributes[key]=value;}}globalThis.document={createElement:tag=>new Element(tag)};try{const registry=createComponentRegistry();componentDefinitions.forEach(definition=>registry.register(definition));const definition=registry.resolve('hero'),node=registry.resolveVariant('hero','split').render(structuredClone(definition.defaultContent)),art=node.children.find(child=>child.className==='variant-art');assert.ok(art);assert.equal(art.textContent,'');assert.equal(art.attributes['aria-hidden'],'true');}finally{globalThis.document=original;}});
test('global settings update atomically and notify subscribers',()=>{const store=createStudioStore(seedState);let observed;store.subscribe(state=>{observed=state.designSettings});store.updateDesignSettings({primaryColor:'#ff0066',radius:24});assert.equal(observed.primaryColor,'#ff0066');assert.equal(observed.radius,24);assert.match(store.exportSnapshot(),/"componentInstanceIds"/)});
test('canvas and Explorer share one selected instance identity across immersive Preview',()=>{const store=createStudioStore(seedState);store.selectComponent('instance-services');const history=store.getHistory().entries.length;store.setMode('preview');assert.equal(store.getState().workspace.selectedComponentId,'instance-services');assert.equal(store.getState().workspace.mode,'preview');store.setPreviewDevice('mobile');store.setMode('edit');assert.equal(store.getState().workspace.mode,'edit');assert.equal(store.getState().workspace.selectedComponentId,'instance-services');assert.equal(store.getHistory().entries.length,history);assert.throws(()=>store.setMode('inspect'),/Invalid mode/)});
test('inline and panel editors share the structured content update path',()=>{const store=createStudioStore(seedState);store.updateComponentContent('instance-hero','heading','A clearer heading');store.updateComponentContent('instance-services','items.0.title','Updated service');assert.equal(store.getState().componentInstances['instance-hero'].content.heading,'A clearer heading');assert.equal(store.getState().componentInstances['instance-services'].content.items[0].title,'Updated service');assert.throws(()=>store.updateComponentContent('missing','heading','No'),/Unknown component instance/)});
test('structural order mutations are centralized and undoable',()=>{const store=createStudioStore(seedState);store.moveComponent('instance-cta',0);assert.equal(store.getActivePage().componentInstanceIds[0],'instance-cta');store.undo();assert.deepEqual(store.getActivePage().componentInstanceIds,seedState.pages['page-home'].componentInstanceIds)});
test('registry defaults insert unique instances and duplicate content independently',()=>{const store=createStudioStore(seedState);const definition=componentDefinitions.find(item=>item.type==='cta');const added=store.insertComponent(definition,1);const copy=store.duplicateComponent(added);assert.notEqual(added,copy);store.updateComponentContent(copy,'heading','Independent copy');assert.notEqual(store.getState().componentInstances[added].content.heading,'Independent copy');assert.equal(store.getActivePage().componentInstanceIds[1],added)});
test('hide show delete and history undo preserve structured content',()=>{const store=createStudioStore(seedState),before=store.getState().componentInstances['instance-services'].content;store.setComponentHidden('instance-services',true);store.setComponentHidden('instance-services',false);store.deleteComponent('instance-services');assert.equal(store.getState().componentInstances['instance-services'],undefined);store.undo();assert.deepEqual(store.getState().componentInstances['instance-services'].content,before)});
test('variant selection validates definition membership and preserves content',()=>{const store=createStudioStore(seedState),hero=componentDefinitions.find(item=>item.type==='hero'),before=store.getState().componentInstances['instance-hero'].content;store.setComponentVariant('instance-hero',hero,'split');store.setComponentVariant('instance-hero',hero,'editorial');assert.deepEqual(store.getState().componentInstances['instance-hero'].content,before);assert.equal(store.getState().componentInstances['instance-hero'].variantId,'editorial');assert.throws(()=>store.setComponentVariant('instance-hero',hero,'unknown'),/Unknown variant/)});
test('insert uses default variant and duplicate preserves variant independently',()=>{const store=createStudioStore(seedState),hero=componentDefinitions.find(item=>item.type==='hero'),added=store.insertComponent(hero,0);assert.equal(store.getState().componentInstances[added].variantId,hero.defaultVariantId);store.setComponentVariant(added,hero,'split');const copy=store.duplicateComponent(added);assert.equal(store.getState().componentInstances[copy].variantId,'split');store.setComponentVariant(copy,hero,'editorial');assert.equal(store.getState().componentInstances[added].variantId,'split')});
test('registry normalizes single-variant definitions and rejects invalid defaults',()=>{const registry=createComponentRegistry().register({type:'single',render:()=>null});assert.equal(registry.resolveVariant('single').id,'default');assert.throws(()=>createComponentRegistry().register({type:'bad',defaultVariantId:'missing',variants:[{id:'only',render:()=>null}]}),/Unknown default variant/)});
test('preview device switches without duplicating page state',()=>{const store=createStudioStore(seedState),page=store.getActivePage();store.setPreviewDevice('tablet');store.setPreviewDevice('mobile');assert.equal(store.getState().workspace.previewDevice,'mobile');assert.deepEqual(store.getActivePage(),page);assert.throws(()=>store.setPreviewDevice('watch'),/Invalid preview device/)});
test('responsive overrides are constrained, explicit, and clearable',()=>{const store=createStudioStore(seedState),hero=componentDefinitions.find(x=>x.type==='hero'),variant=hero.variants.find(x=>x.id==='split');store.setResponsiveOverride('instance-hero',hero,variant,'mobile','alignment','center');store.setResponsiveOverride('instance-hero',hero,variant,'mobile','mobileHeading','Short heading');assert.equal(store.getState().componentInstances['instance-hero'].responsiveOverrides.mobile.mobileHeading,'Short heading');assert.equal(store.getState().componentInstances['instance-hero'].content.heading,seedState.componentInstances['instance-hero'].content.heading);store.clearResponsiveOverride('instance-hero','mobile','mobileHeading');assert.equal(store.getState().componentInstances['instance-hero'].responsiveOverrides.mobile.mobileHeading,undefined);store.clearResponsiveOverride('instance-hero','mobile');assert.deepEqual(store.getState().componentInstances['instance-hero'].responsiveOverrides,{});assert.throws(()=>store.setResponsiveOverride('instance-hero',hero,variant,'mobile','alignment','sideways'),/Invalid responsive value/)});
test('responsive state deep-copies on duplicate and survives history undo',()=>{const store=createStudioStore(seedState),hero=componentDefinitions.find(x=>x.type==='hero'),variant=hero.variants[0];store.setResponsiveOverride('instance-hero',hero,variant,'tablet','visibility',false);const copy=store.duplicateComponent('instance-hero');store.clearResponsiveOverride(copy,'tablet');assert.equal(store.getState().componentInstances['instance-hero'].responsiveOverrides.tablet.visibility,false);store.deleteComponent('instance-hero');store.undo();assert.equal(store.getState().componentInstances['instance-hero'].responsiveOverrides.tablet.visibility,false)});

test('history records document edits but excludes transient workspace state',()=>{const store=createStudioStore(seedState);store.selectComponent('instance-hero');store.setPreviewDevice('mobile');store.setMode('preview');assert.equal(store.getHistory().entries.length,0);store.setMode('edit');store.updateComponentContent('instance-hero','heading','History heading');store.updateDesignSettings({radius:24});assert.equal(store.getHistory().entries.length,2);assert.equal(store.getHistory().entries[0].actor.id,'local-system')});
test('mixed edits support multi-step undo redo and branch invalidation',()=>{const store=createStudioStore(seedState),hero=componentDefinitions.find(x=>x.type==='hero');store.updateComponentContent('instance-hero','heading','Changed');store.setComponentVariant('instance-hero',hero,'split');store.moveComponent('instance-hero',2);store.updateDesignSettings({radius:30});store.setComponentHidden('instance-cta',true);for(let i=0;i<5;i++)store.undo();assert.equal(store.getState().componentInstances['instance-hero'].content.heading,seedState.componentInstances['instance-hero'].content.heading);for(let i=0;i<5;i++)store.redo();assert.equal(store.getState().componentInstances['instance-cta'].hidden,true);store.undo();store.updateDesignSettings({radius:12});assert.equal(store.getHistory().canRedo,false)});
test('restore moves the document to a selected history point',()=>{const store=createStudioStore(seedState);store.updateDesignSettings({radius:10});const first=store.getHistory().entries[0].id;store.updateDesignSettings({radius:32});store.restoreTo(first);assert.equal(store.getState().designSettings.radius,10);assert.equal(store.getHistory().cursor,0)});
test('library validates stable types lifecycle and identities',()=>{const library=createLibraryRegistry();librarySeeds.forEach(item=>library.register(item));assert.equal(library.all().length,15);assert.throws(()=>library.register({...librarySeeds[0],id:'invalid',type:'widget'}),/Unsupported library type/);assert.throws(()=>library.register({...librarySeeds[0],id:'invalid',status:'draft'}),/Unsupported library status/);assert.throws(()=>library.register(librarySeeds[0]),/already registered/)});
test('library default view is certified and filters text type status and tags',()=>{const library=createLibraryRegistry();librarySeeds.forEach(item=>library.register(item));assert.ok(library.query().every(item=>item.status==='certified'));assert.deepEqual(library.query({type:'component'}).map(item=>item.name),['Hero','Services','Call to action']);assert.equal(library.query({status:'experimental'}).length,1);assert.equal(library.query({status:'deprecated'})[0].id,'token.legacy-accent');assert.equal(library.query({search:'consulting',status:'specialty'}).length,1);assert.equal(library.query({tags:['color']}).length,1)});
test('library component items link to runtime definitions without mutating instances',()=>{const library=createLibraryRegistry(),registry=createComponentRegistry();componentDefinitions.forEach(item=>registry.register(item));librarySeeds.forEach(item=>library.register(item));const before=structuredClone(seedState.componentInstances);for(const item of library.query({type:'component'}))assert.equal(registry.resolve(item.payload.definitionType).type,item.payload.definitionType);assert.deepEqual(seedState.componentInstances,before)});
test('library browsing remains outside document transaction history',()=>{const store=createStudioStore(seedState),library=createLibraryRegistry();librarySeeds.forEach(item=>library.register(item));library.query({search:'hero'});library.query({status:'archived'});assert.equal(store.getHistory().entries.length,0)});
test('certified compositions resolve defaults variants and overrides before insertion',()=>{const library=createLibraryRegistry(),registry=createComponentRegistry();librarySeeds.forEach(i=>library.register(i));componentDefinitions.forEach(d=>registry.register(d));const resolved=resolveComposition(library,'composition.lead-intro',registry);assert.deepEqual(resolved.members.map(m=>m.definitionType),['hero','cta']);assert.equal(resolved.members[0].variantId,'split');assert.equal(resolved.members[1].variantId,'default');assert.equal(resolved.members[0].content.heading,'Turn attention into momentum.');assert.equal(componentDefinitions[0].defaultContent.heading,'Your next chapter starts here.')});
test('composition insertion is one atomic history transaction at any index',()=>{const library=createLibraryRegistry(),registry=createComponentRegistry(),store=createStudioStore(seedState);librarySeeds.forEach(i=>library.register(i));componentDefinitions.forEach(d=>registry.register(d));const resolved=resolveComposition(library,'composition.service-home',registry),before=store.getActivePage().componentInstanceIds.length,ids=store.insertComposition(resolved.item,resolved.members,1);assert.equal(ids.length,3);assert.deepEqual(store.getActivePage().componentInstanceIds.slice(1,4),ids);assert.equal(store.getHistory().entries.length,1);store.undo();assert.equal(store.getActivePage().componentInstanceIds.length,before);store.redo();assert.deepEqual(store.getActivePage().componentInstanceIds.slice(1,4),ids)});

test('page navigation is transient while create rename and reorder are transactions',()=>{const store=createStudioStore(seedState),about=store.createPage('About');assert.equal(store.getActivePage().slug,'/about');const count=store.getHistory().entries.length;store.selectPage('page-home');store.selectPage(about);assert.equal(store.getHistory().entries.length,count);store.renamePage(about,'Our Team');assert.equal(store.getActivePage().slug,'/our-team');store.movePage(about,0);assert.equal(store.getState().website.pageIds[0],about)});
test('duplicate page deep copies instances and page edits remain isolated',()=>{const store=createStudioStore(seedState),copy=store.duplicatePage('page-home'),sourceIds=store.getState().pages['page-home'].componentInstanceIds,copyIds=store.getState().pages[copy].componentInstanceIds;assert.equal(copyIds.length,sourceIds.length);assert.ok(copyIds.every(id=>!sourceIds.includes(id)));store.updateComponentContent(copyIds[0],'heading','Independent page');assert.notEqual(store.getState().componentInstances[sourceIds[0]].content.heading,'Independent page')});
test('protected page delete is atomic reversible and preserves one page minimum',()=>{const store=createStudioStore(seedState),about=store.createPage('About');assert.throws(()=>store.deletePage(about),/requires confirmation/);store.deletePage(about,true);assert.equal(store.getState().pages[about],undefined);assert.equal(store.getState().workspace.activePageId,'page-home');store.undo();assert.ok(store.getState().pages[about]);store.redo();assert.equal(store.getState().pages[about],undefined);assert.throws(()=>store.deletePage('page-home',true),/at least one page/)});
test('composition targets only the requested active page and design settings remain global',()=>{const library=createLibraryRegistry(),registry=createComponentRegistry(),store=createStudioStore(seedState);librarySeeds.forEach(i=>library.register(i));componentDefinitions.forEach(d=>registry.register(d));const about=store.createPage('About'),resolved=resolveComposition(library,'composition.lead-intro',registry);store.insertComposition(resolved.item,resolved.members,0);assert.equal(store.getState().pages[about].componentInstanceIds.length,2);assert.equal(store.getState().pages['page-home'].componentInstanceIds.length,3);store.updateDesignSettings({primaryColor:'#123456'});assert.equal(store.getState().designSettings.primaryColor,'#123456')});
test('validation rejects broken multi-page ownership slug and order',()=>{const broken=structuredClone(seedState);broken.website.pageIds.push('page-home');assert.match(validateStudioState(broken).join(';'),/page references must be unique/);const shared=structuredClone(seedState);shared.pages.other={id:'other',websiteId:shared.website.id,name:'Other',slug:'/',componentInstanceIds:['instance-hero']};shared.website.pageIds.push('other');assert.match(validateStudioState(shared).join(';'),/slug must be unique/);assert.match(validateStudioState(shared).join(';'),/multiple pages/)});
test('legacy singleton page input migrates without changing identities or content',()=>{const legacy=structuredClone(seedState);legacy.page=legacy.pages['page-home'];delete legacy.pages;const store=createStudioStore(legacy);assert.equal(store.getActivePage().id,'page-home');assert.deepEqual(store.getActivePage().componentInstanceIds,seedState.pages['page-home'].componentInstanceIds);assert.equal(store.getState().componentInstances['instance-hero'].content.heading,seedState.componentInstances['instance-hero'].content.heading)});
test('composition failures are preflighted without partial mutation',()=>{const library=createLibraryRegistry(),registry=createComponentRegistry(),store=createStudioStore(seedState);librarySeeds.forEach(i=>library.register(i));componentDefinitions.forEach(d=>registry.register(d));const before=store.exportSnapshot();assert.throws(()=>resolveComposition(library,'component.hero',registry),/not a composition/);const invalid=createLibraryRegistry().register({id:'bad',type:'composition',name:'Bad',status:'certified',version:'1',tags:[],description:'',provenance:{source:'test'},payload:{executable:true,members:[{definitionType:'missing'}]}});assert.throws(()=>resolveComposition(invalid,'bad',registry),/Unknown component type/);assert.equal(store.exportSnapshot(),before);assert.equal(store.getHistory().entries.length,0)});
test('generated composition instances remain independent and fully editable',()=>{const library=createLibraryRegistry(),registry=createComponentRegistry(),store=createStudioStore(seedState);librarySeeds.forEach(i=>library.register(i));componentDefinitions.forEach(d=>registry.register(d));const r=resolveComposition(library,'composition.service-home',registry),ids=store.insertComposition(r.item,r.members,0);store.updateComponentContent(ids[0],'heading','Project-owned heading');store.setComponentVariant(ids[0],registry.resolve('hero'),'split');assert.equal(store.getState().componentInstances[ids[0]].sourceLibraryItemId,r.item.id);assert.equal(store.getState().componentInstances[ids[0]].content.heading,'Project-owned heading');assert.notEqual(r.members[0].content.heading,'Project-owned heading')});
test('new sections start with no responsive exceptions',()=>{const store=createStudioStore(seedState),services=componentDefinitions.find(x=>x.type==='services'),id=store.insertComponent(services,1);assert.deepEqual(store.getState().componentInstances[id].responsiveOverrides,{})});

test('certified page templates resolve and flatten composition plus direct members',()=>{const library=createLibraryRegistry(),registry=createComponentRegistry();librarySeeds.forEach(item=>library.register(item));componentDefinitions.forEach(item=>registry.register(item));const templates=library.query({type:'composition'}).filter(item=>item.payload?.kind==='page-template');assert.equal(templates.length,3);const resolved=resolvePageTemplate(library,'page-template.company-story',registry);assert.deepEqual(resolved.members.map(member=>member.definitionType),['hero','cta','services']);assert.equal(resolved.members[2].variantId,'list');assert.equal(resolved.defaultPageName,'About')});
test('page template creation is one atomic transaction with fresh stable identities',()=>{const library=createLibraryRegistry(),registry=createComponentRegistry(),store=createStudioStore(seedState);librarySeeds.forEach(item=>library.register(item));componentDefinitions.forEach(item=>registry.register(item));const resolved=resolvePageTemplate(library,'page-template.service-home',registry),pageId=store.createPageFromTemplate(resolved),page=store.getState().pages[pageId];assert.equal(store.getHistory().entries.length,1);assert.equal(store.getState().workspace.activePageId,pageId);assert.equal(page.sourceLibraryItemId,resolved.item.id);assert.equal(page.componentInstanceIds.length,3);assert.ok(page.componentInstanceIds.every(id=>!seedState.pages['page-home'].componentInstanceIds.includes(id)));store.undo();assert.equal(store.getState().pages[pageId],undefined);assert.ok(page.componentInstanceIds.every(id=>!store.getState().componentInstances[id]));store.redo();assert.deepEqual(store.getState().pages[pageId].componentInstanceIds,page.componentInstanceIds)});
test('repeated template creation resolves slug collisions and independent editable content',()=>{const library=createLibraryRegistry(),registry=createComponentRegistry(),store=createStudioStore(seedState);librarySeeds.forEach(item=>library.register(item));componentDefinitions.forEach(item=>registry.register(item));const resolved=resolvePageTemplate(library,'page-template.lead-capture',registry),first=store.createPageFromTemplate(resolved),second=store.createPageFromTemplate(resolved);assert.notEqual(first,second);assert.equal(store.getState().pages[first].slug,'/contact');assert.equal(store.getState().pages[second].slug,'/contact-2');const firstHero=store.getState().pages[first].componentInstanceIds[0],secondHero=store.getState().pages[second].componentInstanceIds[0];store.updateComponentContent(secondHero,'heading','Independent contact');assert.notEqual(store.getState().componentInstances[firstHero].content.heading,'Independent contact');assert.equal(resolved.members[0].content.heading,'Start a conversation.')});
test('generated template page has no live dependency on its source registry',()=>{const library=createLibraryRegistry(),registry=createComponentRegistry(),store=createStudioStore(seedState);librarySeeds.forEach(item=>library.register(item));componentDefinitions.forEach(item=>registry.register(item));const resolved=resolvePageTemplate(library,'page-template.company-story',registry),pageId=store.createPageFromTemplate(resolved);const snapshot=store.getState().pages[pageId];const emptyLibrary=createLibraryRegistry();assert.throws(()=>emptyLibrary.resolve(resolved.item.id),/Unknown library item/);assert.equal(store.getState().pages[pageId].componentInstanceIds.length,snapshot.componentInstanceIds.length);store.moveComponent(snapshot.componentInstanceIds[2],0);assert.equal(store.getActivePage().componentInstanceIds[0],snapshot.componentInstanceIds[2])});
test('page template failures occur before document mutation',()=>{const registry=createComponentRegistry(),store=createStudioStore(seedState);componentDefinitions.forEach(item=>registry.register(item));const before=store.exportSnapshot(),library=createLibraryRegistry();library.register({id:'bad-template',type:'composition',name:'Bad',status:'certified',version:'1',tags:[],description:'',provenance:{source:'test'},payload:{kind:'page-template',executable:true,defaultPageName:'Bad',members:[{definitionType:'missing'}]}});assert.throws(()=>resolvePageTemplate(library,'bad-template',registry),/Unknown component type/);assert.equal(store.exportSnapshot(),before);assert.equal(store.getHistory().entries.length,0);const wrong=createLibraryRegistry().register({...librarySeeds[0],id:'wrong'});assert.throws(()=>resolvePageTemplate(wrong,'wrong',registry),/not a page template/)});

test('certified starter packages resolve complete ordered page recipes',()=>{const library=createLibraryRegistry(),registry=createComponentRegistry();librarySeeds.forEach(item=>library.register(item));componentDefinitions.forEach(item=>registry.register(item));const packages=library.query({type:'starter-package'}).filter(item=>item.payload?.executable);assert.equal(packages.length,2);const resolved=resolveStarterPackage(library,'starter.service-business',registry);assert.deepEqual(resolved.pages.map(page=>page.name),['Home','About','Contact']);assert.deepEqual(resolved.pages.map(page=>page.slug),['/home','/about','/contact']);assert.deepEqual(resolved.pages[1].members.map(member=>member.definitionType),['hero','cta','services']);assert.equal(resolved.designSettings.primaryColor,'#2563eb')});
test('starter assembly replaces the complete website atomically and applies design settings',()=>{const library=createLibraryRegistry(),registry=createComponentRegistry(),store=createStudioStore(seedState);librarySeeds.forEach(item=>library.register(item));componentDefinitions.forEach(item=>registry.register(item));const before=store.exportSnapshot(),resolved=resolveStarterPackage(library,'starter.service-business',registry);assert.throws(()=>store.replaceWebsiteFromStarter(resolved),/requires confirmation/);const websiteId=store.replaceWebsiteFromStarter(resolved,true),assembled=store.getState();assert.equal(assembled.website.id,websiteId);assert.equal(assembled.website.sourceLibraryItemId,resolved.item.id);assert.deepEqual(assembled.website.pageIds.map(id=>assembled.pages[id].name),['Home','About','Contact']);assert.equal(assembled.designSettings.primaryColor,'#2563eb');assert.equal(store.getHistory().entries.length,1);const assembledSnapshot=store.exportSnapshot();store.undo();assert.equal(store.exportSnapshot(),before);store.redo();assert.equal(store.exportSnapshot(),assembledSnapshot)});
test('repeated starter assemblies receive fresh independent identities',()=>{const library=createLibraryRegistry(),registry=createComponentRegistry(),store=createStudioStore(seedState);librarySeeds.forEach(item=>library.register(item));componentDefinitions.forEach(item=>registry.register(item));const resolved=resolveStarterPackage(library,'starter.lead-generation',registry);store.replaceWebsiteFromStarter(resolved,true);const first=store.getState(),firstPageIds=[...first.website.pageIds],firstInstanceIds=Object.keys(first.componentInstances);store.replaceWebsiteFromStarter(resolved,true);const second=store.getState();assert.notEqual(first.website.id,second.website.id);assert.ok(second.website.pageIds.every(id=>!firstPageIds.includes(id)));assert.ok(Object.keys(second.componentInstances).every(id=>!firstInstanceIds.includes(id)));const hero=second.pages[second.website.pageIds[0]].componentInstanceIds[0];store.updateComponentContent(hero,'heading','Campaign edit');assert.equal(store.getState().componentInstances[hero].content.heading,'Campaign edit')});
test('assembled website remains detached and supports page-template creation',()=>{const library=createLibraryRegistry(),registry=createComponentRegistry(),store=createStudioStore(seedState);librarySeeds.forEach(item=>library.register(item));componentDefinitions.forEach(item=>registry.register(item));const packageRecipe=resolveStarterPackage(library,'starter.lead-generation',registry);store.replaceWebsiteFromStarter(packageRecipe,true);const emptyLibrary=createLibraryRegistry();assert.throws(()=>emptyLibrary.resolve(packageRecipe.item.id),/Unknown library item/);const pageRecipe=resolvePageTemplate(library,'page-template.service-home',registry),pageId=store.createPageFromTemplate(pageRecipe,'Services');assert.equal(store.getState().workspace.activePageId,pageId);store.movePage(pageId,0);assert.equal(store.getState().website.pageIds[0],pageId)});
test('starter package validation fails before mutation and blank replacement remains available',()=>{const registry=createComponentRegistry(),store=createStudioStore(seedState);componentDefinitions.forEach(item=>registry.register(item));const before=store.exportSnapshot(),bad=createLibraryRegistry();bad.register({id:'bad-starter',type:'starter-package',name:'Bad',status:'certified',version:'1',tags:[],description:'',provenance:{source:'test'},payload:{executable:true,recommendedWebsiteName:'Bad',pageTemplates:[{pageTemplateId:'missing'}],designSettings:{unsupported:true}}});assert.throws(()=>resolveStarterPackage(bad,'bad-starter',registry));assert.equal(store.exportSnapshot(),before);store.replaceWithBlankWebsite('Custom Site',true);assert.equal(store.getState().website.name,'Custom Site');assert.equal(store.getState().website.pageIds.length,1);assert.equal(store.getActivePage().componentInstanceIds.length,0)});

test('component and page conversations use structured collaboration state outside document history',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),before=store.getHistory().entries.length;const component=comments.create({pageId:'page-home',componentInstanceId:'instance-hero',body:'Review this heading',author:'client'}),page=comments.create({pageId:'page-home',body:'Check the overall flow',author:'rally-staff'});assert.notEqual(component,page);assert.equal(comments.get(component).status,'open');assert.equal(comments.get(component).messages[0].author.id,'client');comments.reply(component,'We can revise it.','rally-staff');assert.equal(comments.get(component).messages.length,2);assert.equal(store.getHistory().entries.length,before)});
test('conversation statuses filters and reopen follow the approved state model',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),first=comments.create({pageId:'page-home',body:'First'}),second=comments.create({pageId:'page-home',body:'Second'});comments.setStatus(first,'waiting-on-client');comments.resolve(second);assert.equal(comments.get(second).status,'resolved');assert.equal(comments.list().length,1);comments.setFilters({status:'resolved'});assert.deepEqual(comments.list().map(item=>item.id),[second]);comments.reopen(second);assert.equal(comments.get(second).status,'open');assert.throws(()=>comments.setStatus(first,'closed'),/Unsupported conversation status/)});
test('conversation selection navigates across pages without document history',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),about=store.createPage('About'),cta=componentDefinitions.find(item=>item.type==='cta'),instance=store.insertComponent(cta,0),id=comments.create({pageId:about,componentInstanceId:instance,body:'About CTA'});store.selectPage('page-home');const count=store.getHistory().entries.length,anchor=comments.select(id);assert.equal(anchor.available,true);assert.equal(store.getState().workspace.activePageId,about);assert.equal(store.getState().workspace.selectedComponentId,instance);assert.equal(store.getHistory().entries.length,count);comments.setFilters({page:'current',status:'all'});assert.equal(comments.list().length,1)});
test('deleted component and page anchors remain retained and restore by stable identity',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),component=comments.create({pageId:'page-home',componentInstanceId:'instance-hero',body:'Keep context'});store.deleteComponent('instance-hero');assert.equal(comments.get(component).anchorState.componentAvailable,false);assert.equal(comments.getState().order.length,1);store.undo();assert.equal(comments.get(component).anchorState.available,true);const about=store.createPage('About'),pageComment=comments.create({pageId:about,body:'About review'});store.deletePage(about,true);assert.equal(comments.get(pageComment).anchorState.pageAvailable,false);store.undo();assert.equal(comments.get(pageComment).anchorState.pageAvailable,true)});
test('website replacement retains prior conversations as unavailable and history does not undo collaboration',()=>{const library=createLibraryRegistry(),registry=createComponentRegistry(),store=createStudioStore(seedState),comments=createConversationStore(store);librarySeeds.forEach(item=>library.register(item));componentDefinitions.forEach(item=>registry.register(item));const id=comments.create({pageId:'page-home',body:'Prior website context'});comments.reply(id,'Still retained');comments.resolve(id);const resolved=resolveStarterPackage(library,'starter.lead-generation',registry);store.replaceWebsiteFromStarter(resolved,true);assert.equal(comments.get(id).anchorState.websiteAvailable,false);store.undo();assert.equal(comments.get(id).anchorState.pageAvailable,true);assert.equal(comments.get(id).messages.length,2);assert.equal(comments.get(id).status,'resolved')});

test('review session lifecycle captures one stable lightweight checkpoint',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),reviews=createReviewSessionStore(store,comments),id=reviews.create('Client review','rally-staff');assert.equal(reviews.get(id).status,'draft');assert.equal(reviews.get(id).checkpoint,null);reviews.start(id);const checkpoint=reviews.get(id).checkpoint;assert.equal(reviews.get(id).status,'active');assert.equal(checkpoint.websiteId,seedState.website.id);assert.equal(checkpoint.pageCount,1);store.updateDesignSettings({radius:31});assert.deepEqual(reviews.get(id).checkpoint,checkpoint);reviews.complete(id);assert.equal(reviews.get(id).status,'completed');assert.ok(reviews.get(id).completedAt);assert.throws(()=>reviews.start(id),/cannot be restarted/)});
test('active sessions associate new and existing conversations by stable reference',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),reviews=createReviewSessionStore(store,comments),existing=comments.create({pageId:'page-home',body:'Existing'}),id=reviews.create('Scope review');reviews.start(id);const created=comments.create({pageId:'page-home',componentInstanceId:'instance-services',body:'New in session'});assert.equal(comments.get(created).reviewSessionId,id);reviews.associateConversation(id,existing);assert.equal(comments.get(existing).reviewSessionId,id);assert.deepEqual(reviews.get(id).conversationIds,[existing,created]);assert.equal(comments.get(existing).messages.length,1)});
test('readiness counts statuses but never automatically approves',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),reviews=createReviewSessionStore(store,comments),id=reviews.create('Readiness');reviews.start(id);const open=comments.create({pageId:'page-home',body:'Open'}),waiting=comments.create({pageId:'page-home',body:'Waiting'});comments.setStatus(waiting,'waiting-on-client');let review=reviews.get(id);assert.equal(review.summary.ready,false);assert.deepEqual(review.summary.counts,{open:1,'waiting-on-rally':0,'waiting-on-client':1,resolved:0});assert.equal(review.currentApproval,null);comments.resolve(open);comments.resolve(waiting);review=reviews.get(id);assert.equal(review.summary.ready,true);assert.equal(review.currentApproval,null)});
test('approval gating override revocation and reapproval preserve append-only audit',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),reviews=createReviewSessionStore(store,comments),id=reviews.create('Approval');reviews.start(id);comments.create({pageId:'page-home',body:'Unresolved'});assert.throws(()=>reviews.approve(id),/override reason/);const approved=reviews.approve(id,{approvedBy:'client',overrideReason:'Launch timing accepted'});assert.equal(approved.checkpointId,reviews.get(id).checkpoint.id);assert.equal(approved.overrideReason,'Launch timing accepted');const revoked=reviews.revoke(id,{revokedBy:'client',note:'Reconsidering'});assert.equal(revoked.action,'revoked');comments.resolve(reviews.get(id).conversationIds[0]);reviews.respond(id,'direction','yes','client');reviews.respond(id,'message','very-clear','client');const reapproved=reviews.approve(id,{approvedBy:'client'});assert.notEqual(reapproved.id,approved.id);assert.deepEqual(reviews.get(id).approvalRecords.map(record=>record.action),['approved','revoked','approved'])});
test('post-approval activity and Website edits preserve approval history outside document undo',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),reviews=createReviewSessionStore(store,comments),id=reviews.create('Final review');reviews.start(id);reviews.respond(id,'direction','yes');reviews.respond(id,'message','mostly-clear');const approval=reviews.approve(id);const historyCount=store.getHistory().entries.length;const conversation=comments.create({pageId:'page-home',body:'New concern'});assert.equal(reviews.get(id).summary.ready,false);assert.equal(reviews.get(id).currentApproval.id,approval.id);assert.equal(store.getHistory().entries.length,historyCount);store.updateComponentContent('instance-hero','heading','Edited after approval');store.undo();assert.equal(reviews.get(id).approvalRecords.length,1);assert.equal(comments.get(conversation).status,'open');store.replaceWithBlankWebsite('Replacement',true);assert.equal(reviews.listCurrentWebsite().length,0);assert.equal(reviews.get(id).websiteId,seedState.website.id);assert.equal(reviews.get(id).approvalRecords[0].id,approval.id)});

test('explicit conversation handoff creates a separate task with complete source references',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),reviews=createReviewSessionStore(store,comments),tasks=createTaskStore(store,comments),session=reviews.create('Task review');reviews.start(session);const conversation=comments.create({pageId:'page-home',componentInstanceId:'instance-hero',body:'Revise headline',author:'client'}),id=tasks.createFromConversation(conversation,{title:'Rewrite hero',description:'Clarify the value proposition',assignedTo:'rally-staff'}),task=tasks.get(id);assert.equal(task.websiteId,seedState.website.id);assert.equal(task.sourceConversationId,conversation);assert.equal(task.reviewSessionId,session);assert.equal(task.pageId,'page-home');assert.equal(task.componentInstanceId,'instance-hero');assert.equal(task.status,'todo');assert.equal(task.assignedTo.id,'rally-staff');assert.deepEqual(comments.get(conversation).linkedTaskIds,[id]);assert.equal(store.getHistory().entries.length,0)});
test('task fields and lifecycle remain independent from conversation and review state',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),reviews=createReviewSessionStore(store,comments),tasks=createTaskStore(store,comments),session=reviews.create('Independent lifecycle');reviews.start(session);const conversation=comments.create({pageId:'page-home',body:'Needs work'}),id=tasks.createFromConversation(conversation,{title:'Initial'});tasks.update(id,{title:'Updated',description:'Implementation detail',assignedTo:'client'});tasks.setStatus(id,'in-progress');tasks.setStatus(id,'done');assert.ok(tasks.get(id).completedAt);assert.equal(comments.get(conversation).status,'open');assert.equal(reviews.get(session).summary.ready,false);comments.resolve(conversation);assert.equal(tasks.get(id).status,'done');assert.equal(reviews.get(session).summary.ready,true);tasks.setStatus(id,'blocked');assert.equal(tasks.get(id).completedAt,null);assert.equal(comments.get(conversation).status,'resolved');assert.equal(store.getHistory().entries.length,0)});
test('task filtering supports the approved compact workflow statuses',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),tasks=createTaskStore(store,comments),first=tasks.createFromConversation(comments.create({pageId:'page-home',body:'First'}),{title:'First'}),second=tasks.createFromConversation(comments.create({pageId:'page-home',body:'Second'}),{title:'Second'});tasks.setStatus(second,'blocked');tasks.setFilter('blocked');assert.deepEqual(tasks.list().map(item=>item.id),[second]);tasks.setFilter('todo');assert.deepEqual(tasks.list().map(item=>item.id),[first]);assert.throws(()=>tasks.setStatus(first,'resolved'),/Unsupported task status/)});
test('task source navigation follows stable page and component anchors',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),tasks=createTaskStore(store,comments),about=store.createPage('About'),definition=componentDefinitions.find(item=>item.type==='cta'),component=store.insertComponent(definition,0),conversation=comments.create({pageId:about,componentInstanceId:component,body:'Fix CTA'}),id=tasks.createFromConversation(conversation,{title:'CTA task'});store.selectPage('page-home');const count=store.getHistory().entries.length,source=tasks.select(id);assert.equal(source.available,true);assert.equal(store.getState().workspace.activePageId,about);assert.equal(store.getState().workspace.selectedComponentId,component);assert.equal(store.getHistory().entries.length,count);store.deleteComponent(component);assert.equal(tasks.get(id).sourceState.available,false);store.undo();assert.equal(tasks.get(id).sourceState.available,true)});
test('tasks survive Website replacement and document undo without entering Website history',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),tasks=createTaskStore(store,comments),conversation=comments.create({pageId:'page-home',body:'Retain task'}),id=tasks.createFromConversation(conversation,{title:'Persistent task'});tasks.setStatus(id,'in-progress');store.replaceWithBlankWebsite('Replacement',true);assert.equal(tasks.get(id).sourceState.websiteAvailable,false);assert.equal(tasks.list().length,0);store.undo();assert.equal(tasks.get(id).sourceState.available,true);assert.equal(tasks.get(id).status,'in-progress');assert.deepEqual(tasks.list().map(item=>item.id),[id])});

test('guided review seeds ordered question types and derives progress from responses',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),reviews=createReviewSessionStore(store,comments),id=reviews.create('Guided');reviews.start(id);const initial=reviews.get(id);assert.deepEqual(initial.questions.map(question=>question.type),['yes-no','single-choice','yes-no','free-text']);assert.deepEqual(initial.questions.map(question=>question.position),[1,2,3,4]);assert.equal(initial.questionnaireSummary.state,'draft');const response=reviews.respond(id,'direction','yes','client');assert.equal(response.actor.id,'client');assert.equal(reviews.get(id).questionnaireSummary.state,'in-progress');const createdAt=response.createdAt;reviews.respond(id,'direction','no','rally-staff');assert.equal(reviews.get(id).responses.direction.createdAt,createdAt);assert.equal(reviews.get(id).responses.direction.actor.id,'rally-staff');reviews.respond(id,'message','mostly-clear','client');assert.equal(reviews.get(id).questionnaireSummary.requiredComplete,true);reviews.respond(id,'visual-style','yes');reviews.respond(id,'missing','Add customer proof');assert.equal(reviews.get(id).questionnaireSummary.state,'completed')});
test('required questionnaire answers gate approval with intentional override evidence',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),reviews=createReviewSessionStore(store,comments),id=reviews.create('Question gating');reviews.start(id);assert.throws(()=>reviews.approve(id),/unanswered required review questions/);const overridden=reviews.approve(id,{overrideReason:'Client approved before completing the guided review'});assert.deepEqual(overridden.overriddenBlockers,['unanswered required review questions']);reviews.revoke(id);reviews.respond(id,'direction','yes');reviews.respond(id,'message','very-clear');assert.equal(reviews.get(id).currentApproval,null);const approved=reviews.approve(id);assert.equal(approved.overrideReason,null);assert.equal(reviews.get(id).approvalRecords.length,3)});
test('questionnaire responses remain independent from conversations tasks approvals and Website history',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),reviews=createReviewSessionStore(store,comments),tasks=createTaskStore(store,comments),id=reviews.create('Separation');reviews.start(id);reviews.respond(id,'direction','yes');const history=store.getHistory().entries.length,conversation=comments.create({pageId:'page-home',body:'Review issue'}),task=tasks.createFromConversation(conversation,{title:'Address issue'});comments.resolve(conversation);comments.reopen(conversation);tasks.setStatus(task,'done');store.updateComponentContent('instance-hero','heading','Temporary edit');store.undo();assert.equal(reviews.get(id).responses.direction.answer,'yes');assert.equal(store.getHistory().entries.length,history+1);assert.equal(reviews.get(id).approvalRecords.length,0);assert.equal(comments.get(conversation).status,'open');assert.equal(tasks.get(task).status,'done')});
test('completed Review Sessions retain inspectable responses without automatic approval',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),reviews=createReviewSessionStore(store,comments),id=reviews.create('Complete questionnaire');assert.throws(()=>reviews.respond(id,'direction','yes'),/must be started/);reviews.start(id);for(const [question,answer] of [['direction','yes'],['message','very-clear'],['visual-style','yes'],['missing','Nothing else']])reviews.respond(id,question,answer,'client');assert.equal(reviews.get(id).questionnaireSummary.state,'completed');assert.equal(reviews.get(id).currentApproval,null);reviews.complete(id);assert.equal(reviews.get(id).status,'completed');assert.equal(reviews.get(id).responses.missing.answer,'Nothing else');assert.throws(()=>reviews.respond(id,'direction','no'),/read-only/)});

test('manual Review Version captures an immutable complete document outside Workspace history',()=>{const store=createStudioStore(seedState),versions=createReviewVersionStore(store),before=store.getHistory().entries.length,id=versions.create({label:'Website V1',createdBy:'rally-staff'}),captured=versions.get(id);assert.equal(captured.websiteId,seedState.website.id);assert.equal(captured.pageCount,1);assert.equal(captured.componentCount,3);assert.equal(store.getHistory().entries.length,before);store.updateComponentContent('instance-hero','heading','New current heading');store.updateDesignSettings({radius:37});assert.notEqual(versions.get(id).snapshot.componentInstances['instance-hero'].content.heading,'New current heading');assert.notEqual(versions.get(id).snapshot.designSettings.radius,37);assert.equal(versions.get(id).isCurrent,false)});
test('Review Session checkpoint and approval link to one stable Review Version',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),versions=createReviewVersionStore(store),reviews=createReviewSessionStore(store,comments,versions),id=reviews.create('Linked review');reviews.start(id);const review=reviews.get(id),version=versions.get(review.reviewVersionId);assert.equal(review.checkpoint.reviewVersionId,version.id);assert.equal(version.reviewSessionId,id);assert.equal(version.source,'review-session-start');reviews.respond(id,'direction','yes');reviews.respond(id,'message','very-clear');const approval=reviews.approve(id);assert.equal(approval.reviewVersionId,version.id);assert.equal(versions.list().length,1)});
test('inspection and rename preserve current document snapshot and Workspace history',()=>{const store=createStudioStore(seedState),versions=createReviewVersionStore(store),id=versions.create({label:'Before changes'}),before=store.exportSnapshot(),history=store.getHistory().entries.length,snapshot=versions.inspect(id);snapshot.website.name='Mutated caller copy';assert.equal(store.exportSnapshot(),before);assert.equal(versions.get(id).snapshot.website.name,seedState.website.name);versions.rename(id,'Website V1');versions.exitInspection();assert.equal(versions.get(id).label,'Website V1');assert.equal(store.getHistory().entries.length,history);assert.equal(versions.getState().inspectingId,null)});
test('restoring a Review Version is one undoable transaction with exact stable identities',()=>{const store=createStudioStore(seedState),versions=createReviewVersionStore(store),id=versions.create({label:'Website V1'}),oldSnapshot=versions.get(id).snapshot;store.replaceWithBlankWebsite('New Website',true);const newer=store.exportSnapshot(),beforeCount=store.getHistory().entries.length;assert.throws(()=>versions.restore(id),/requires confirmation/);versions.restore(id,true);assert.deepEqual(JSON.parse(store.exportSnapshot()),oldSnapshot);assert.equal(store.getHistory().entries.length,beforeCount+1);store.undo();assert.equal(store.exportSnapshot(),newer);store.redo();assert.deepEqual(JSON.parse(store.exportSnapshot()),oldSnapshot);store.updateComponentContent('instance-hero','heading','Post-restore edit');assert.notEqual(versions.get(id).snapshot.componentInstances['instance-hero'].content.heading,'Post-restore edit')});
test('version restore retains collaboration workflow and natural anchor availability',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),tasks=createTaskStore(store,comments),versions=createReviewVersionStore(store),old=versions.create({label:'Original'}),conversation=comments.create({pageId:'page-home',componentInstanceId:'instance-hero',body:'Original anchor'}),task=tasks.createFromConversation(conversation,{title:'Original task'});store.replaceWithBlankWebsite('Replacement',true);const replacementConversation=comments.create({pageId:store.getState().workspace.activePageId,body:'Replacement anchor'});assert.equal(comments.get(conversation).anchorState.available,false);versions.restore(old,true);assert.equal(comments.get(conversation).anchorState.available,true);assert.equal(tasks.get(task).sourceState.available,true);assert.equal(comments.get(replacementConversation).anchorState.available,false);assert.equal(comments.getState().order.length,2);assert.equal(tasks.get(task).status,'todo')});
test('new versions after edits retain distinct fingerprints and unbounded formal history',()=>{const store=createStudioStore(seedState),versions=createReviewVersionStore(store),first=versions.create({label:'V1'});store.updateComponentContent('instance-hero','heading','V2 heading');const second=versions.create({label:'V2'});assert.notEqual(first,second);assert.notEqual(versions.get(first).documentFingerprint,versions.get(second).documentFingerprint);assert.equal(versions.list().length,2);store.undo();assert.equal(versions.list().length,2)});

test('Discovery definitions have a distinct versioned semantic domain and ordered structure',()=>{assert.equal(websiteDiscoveryQuestionnaire.id,'website-discovery');assert.equal(websiteDiscoveryQuestionnaire.domain,'discovery');assert.equal(websiteDiscoveryQuestionnaire.version,'1.0.0');assert.deepEqual(websiteDiscoveryQuestionnaire.sections.map(section=>section.position),[1,2,3,4,5]);assert.ok(websiteDiscoveryQuestionnaire.sections.every(section=>section.questionIds.every(id=>websiteDiscoveryQuestionnaire.questions.some(question=>question.id===id&&question.sectionId===section.id))));assert.deepEqual(new Set(websiteDiscoveryQuestionnaire.questions.map(question=>question.type)),new Set(['short-text','long-text','yes-no','single-choice','multi-choice']))});
test('Discovery responses support all types while preserving identity and timestamps on update',()=>{const store=createStudioStore(seedState),discovery=createDiscoveryStore(store),id=discovery.create('client');assert.equal(discovery.get(id).progress.state,'draft');discovery.respond(id,'business-summary','Advisory services','client');discovery.respond(id,'audience-primary','Growth teams');discovery.respond(id,'goal-primary','generate-leads');discovery.respond(id,'required-pages',['home','services','contact']);discovery.respond(id,'proof-available','yes');const first=discovery.get(id).responses['business-summary'];discovery.respond(id,'business-summary','Strategic advisory services','rally-staff');const updated=discovery.get(id).responses['business-summary'];assert.equal(updated.id,first.id);assert.equal(updated.createdAt,first.createdAt);assert.equal(updated.answeredBy.id,'rally-staff');assert.deepEqual(discovery.get(id).responses['required-pages'].answer,['home','services','contact']);assert.throws(()=>discovery.respond(id,'goal-primary','unknown'),/Unsupported Discovery answer/)});
test('Discovery accepts incremental text persistence without changing response identity',()=>{const store=createStudioStore(seedState),discovery=createDiscoveryStore(store),id=discovery.create(),sentence='A complete advisory business serving growing teams.';let responseId;for(let index=1;index<=sentence.length;index++){const expected=sentence.slice(0,index).trim(),response=discovery.respond(id,'business-summary',sentence.slice(0,index));responseId??=response.id;assert.equal(response.id,responseId);assert.equal(response.answer,expected);assert.equal(discovery.get(id).progress.answered,1);}discovery.respond(id,'business-summary','A complete advisory business serving teams.');assert.equal(discovery.get(id).responses['business-summary'].id,responseId);assert.equal(discovery.getRecommendationInputs(id).business.summary,'A complete advisory business serving teams.')});
test('Discovery progress and clearing are derived per section and required completion',()=>{const store=createStudioStore(seedState),discovery=createDiscoveryStore(store),id=discovery.create();for(const [question,answer] of [['business-summary','Business'],['audience-primary','Audience'],['goal-primary','inform'],['action-primary','Contact us'],['required-pages',['home']],['brand-direction',['confident']]])discovery.respond(id,question,answer);let progress=discovery.get(id).progress;assert.equal(progress.state,'completed');assert.equal(progress.requiredAnswered,progress.requiredTotal);assert.equal(progress.sections.find(section=>section.id==='business').complete,true);discovery.respond(id,'audience-primary','');progress=discovery.get(id).progress;assert.equal(progress.state,'in-progress');assert.equal(progress.sections.find(section=>section.id==='business').complete,false);assert.equal(discovery.get(id).responses['audience-primary'],undefined)});
