test('Discovery remains independent from Website Review collaboration workflow and restore',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),tasks=createTaskStore(store,comments),versions=createReviewVersionStore(store),reviews=createReviewSessionStore(store,comments,versions),discovery=createDiscoveryStore(store),setId=discovery.create(),version=versions.create({label:'Before'});discovery.respond(setId,'business-summary','Persistent context');const review=reviews.create('Separate review');reviews.start(review);reviews.respond(review,'direction','yes');const conversation=comments.create({pageId:'page-home',body:'Review note'}),task=tasks.createFromConversation(conversation,{title:'Task'});store.updateComponentContent('instance-hero','heading','New heading');store.undo();versions.restore(version,true);assert.equal(discovery.get(setId).responses['business-summary'].answer,'Persistent context');assert.equal(reviews.get(review).responses.direction.answer,'yes');assert.equal(comments.get(conversation).status,'open');assert.equal(tasks.get(task).status,'todo');assert.equal(discovery.get(setId).contextAvailable,true);store.replaceWithBlankWebsite('Replacement',true);assert.equal(discovery.get(setId).contextAvailable,false)});

test('Strategy records expose stable sections fields identity and derived initial lifecycle',()=>{const store=createStudioStore(seedState),discovery=createDiscoveryStore(store),strategies=createStrategyStore(store,discovery),id=strategies.ensureCurrent(),item=strategies.get(id);assert.equal(item.websiteId,seedState.website.id);assert.equal(item.progress.state,'draft');assert.equal(item.discoveryResponseSetId,discovery.getState().selectedId);assert.ok(new Set(strategyFields.map(field=>field.section)).size>=8);assert.ok(item.progress.requiredTotal>=7);assert.ok(strategyFields.some(field=>field.key==='message.positioning'&&field.required))});
test('Draft Strategy maps normalized Discovery inputs deterministically with provenance',()=>{const store=createStudioStore(seedState),discovery=createDiscoveryStore(store),set=discovery.create();for(const [question,answer] of [['business-summary','Advisory practice'],['audience-primary','Founders'],['goal-primary','generate-leads'],['action-primary','Book a call'],['required-pages',['home','services']],['brand-direction',['confident','approachable']],['features',['contact-form']]])discovery.respond(set,question,answer);const strategies=createStrategyStore(store,discovery),id=strategies.create(set);strategies.draftFromDiscovery(id);const item=strategies.get(id);assert.equal(item.fields['business.summary'].value,'Advisory practice');assert.deepEqual(item.fields['content.requiredPages'].value,['home','services']);assert.equal(item.fields['goals.primary'].source,'discovery');assert.deepEqual(item.fields['goals.primary'].sourceKeys,['goals.primary']);assert.equal(item.fields['goals.primary'].sourceResponseSetId,set);assert.equal(item.fields['business.primaryOffering'].source,'unresolved');assert.equal(item.progress.state,'in-progress')});
test('human Strategy edits are protected while Discovery-backed fields refresh explicitly',()=>{const store=createStudioStore(seedState),discovery=createDiscoveryStore(store),set=discovery.create();discovery.respond(set,'business-summary','Original');discovery.respond(set,'audience-primary','Original audience');const strategies=createStrategyStore(store,discovery),id=strategies.create(set);strategies.draftFromDiscovery(id);strategies.edit(id,'business.summary','Human interpretation','rally-staff');discovery.respond(set,'business-summary','New evidence');discovery.respond(set,'audience-primary','New audience');let item=strategies.get(id);assert.equal(item.fields['business.summary'].value,'Human interpretation');assert.ok(item.staleFields.includes('audience.primary'));strategies.draftFromDiscovery(id);item=strategies.get(id);assert.equal(item.fields['business.summary'].value,'Human interpretation');assert.equal(item.fields['business.summary'].source,'human');assert.equal(item.fields['audience.primary'].value,'New audience');assert.equal(item.staleFields.length,0)});
test('Strategy readiness and normalized output derive from human-owned decisions',()=>{const store=createStudioStore(seedState),discovery=createDiscoveryStore(store),strategies=createStrategyStore(store,discovery),id=strategies.ensureCurrent();for(const field of strategyFields.filter(field=>field.required))strategies.edit(id,field.key,field.kind==='list'?['value']:`${field.label} decision`);assert.equal(strategies.get(id).progress.state,'ready');const output=strategies.getStrategyOutput(id);assert.equal(output.business.primaryOffering,'Primary offering / value decision');assert.equal(output.message.positioning,'Core message direction decision');assert.deepEqual(output.brand.direction,['value']);assert.equal(store.getHistory().entries.length,0)});
test('Strategy consecutive input-sized edits retain the latest value and human provenance',()=>{const store=createStudioStore(seedState),discovery=createDiscoveryStore(store),strategies=createStrategyStore(store,discovery),id=strategies.ensureCurrent();for(const key of ['business.primaryOffering','audience.context','message.positioning']){strategies.edit(id,key,'a','rally-staff');strategies.edit(id,key,'ab','rally-staff');strategies.edit(id,key,'a','rally-staff');const field=strategies.get(id).fields[key];assert.equal(field.value,'a');assert.equal(field.source,'human');assert.equal(field.humanEdited,true);}assert.equal(store.getHistory().entries.length,0)});
test('Certified component Library inventory inserts one selected ordinary instance with Undo Redo',()=>{const store=createStudioStore(seedState),library=createLibraryRegistry(),registry=createComponentRegistry();librarySeeds.forEach(item=>library.register(item));componentDefinitions.forEach(item=>registry.register(item));const item=library.query({type:'component',status:'certified'})[0],definition=registry.resolve(item.payload.definitionType),before=store.getActivePage().componentInstanceIds.length,history=store.getHistory().entries.length,id=store.insertComponent(definition,before);assert.equal(store.getActivePage().componentInstanceIds.at(-1),id);assert.equal(store.getState().workspace.selectedComponentId,id);assert.equal(store.getHistory().entries.length,history+1);store.undo();assert.equal(store.getActivePage().componentInstanceIds.length,before);store.redo();assert.equal(store.getActivePage().componentInstanceIds.at(-1),id)});
test('Strategy stays separate from Discovery Website history versions and review workflow',()=>{const store=createStudioStore(seedState),comments=createConversationStore(store),tasks=createTaskStore(store,comments),versions=createReviewVersionStore(store),reviews=createReviewSessionStore(store,comments,versions),discovery=createDiscoveryStore(store),set=discovery.create(),strategies=createStrategyStore(store,discovery),strategy=strategies.create(set),version=versions.create({label:'Before'});discovery.respond(set,'business-summary','Evidence');strategies.draftFromDiscovery(strategy);strategies.edit(strategy,'message.positioning','Focused position');const review=reviews.create('Review');reviews.start(review);const conversation=comments.create({pageId:'page-home',body:'Note'}),task=tasks.createFromConversation(conversation,{title:'Task'});store.updateComponentContent('instance-hero','heading','Changed');store.undo();versions.restore(version,true);assert.equal(strategies.get(strategy).fields['message.positioning'].value,'Focused position');assert.equal(discovery.get(set).responses['business-summary'].answer,'Evidence');assert.equal(reviews.get(review).status,'active');assert.equal(comments.get(conversation).status,'open');assert.equal(tasks.get(task).status,'todo');assert.equal(store.getState().componentInstances['instance-hero'].content.heading,seedState.componentInstances['instance-hero'].content.heading)});

test('Strategy Packet opens over existing Discovery and Strategy identities without duplication',()=>{const store=createStudioStore(seedState),discovery=createDiscoveryStore(store),strategies=createStrategyStore(store,discovery),packet=createStrategyPacketStore(store,discovery,strategies),history=store.getHistory().entries.length,id=packet.open(),view=packet.getState();assert.ok(id);assert.equal(view.discoveryResponseSetId,discovery.getState().selectedId);assert.equal(view.strategyId,strategies.getState().selectedId);packet.close();packet.open();assert.equal(discovery.getState().order.length,1);assert.equal(strategies.getState().order.length,1);assert.equal(store.getHistory().entries.length,history)});
test('Packet navigation and preview Page selection are transient Website-history-free state',()=>{const store=createStudioStore(seedState),discovery=createDiscoveryStore(store),strategies=createStrategyStore(store,discovery),packet=createStrategyPacketStore(store,discovery,strategies);packet.open();const about=store.createPage('About'),history=store.getHistory().entries.length;packet.setStep('strategy');packet.next();packet.next();packet.previous();packet.setPreviewPage(about);assert.equal(packet.getState().previewPageId,about);assert.equal(packet.getState().currentStep,'recommendations');assert.equal(store.getHistory().entries.length,history);assert.throws(()=>packet.setStep('approval'),/Unknown packet step/)});
test('Packet Strategy edits reuse the same Strategy record and Discovery stays read-only',()=>{const store=createStudioStore(seedState),discovery=createDiscoveryStore(store),set=discovery.create(),strategies=createStrategyStore(store,discovery),strategy=strategies.create(set),packet=createStrategyPacketStore(store,discovery,strategies);discovery.respond(set,'business-summary','Evidence');packet.open();const before=discovery.get(set).responses;strategies.edit(packet.getState().strategyId,'message.positioning','Shared packet edit');assert.equal(strategies.get(strategy).fields['message.positioning'].value,'Shared packet edit');assert.deepEqual(discovery.get(set).responses,before);assert.equal(store.getHistory().entries.length,0)});
test('Packet Design Direction uses canonical settings transactions with Undo Redo and live state',()=>{const store=createStudioStore(seedState),discovery=createDiscoveryStore(store),strategies=createStrategyStore(store,discovery),packet=createStrategyPacketStore(store,discovery,strategies);packet.open();packet.setStep('design');const before=store.getState().designSettings,history=store.getHistory().entries.length;store.updateDesignSettings({primaryColor:'#ff0066'});store.updateDesignSettings({secondaryColor:'#101828'});store.updateDesignSettings({radius:30});store.updateDesignSettings({spacing:40});store.updateDesignSettings({fontFamily:'Georgia, serif'});assert.deepEqual(store.getState().designSettings,{...before,primaryColor:'#ff0066',secondaryColor:'#101828',radius:30,spacing:40,fontFamily:'Georgia, serif'});assert.equal(store.getHistory().entries.length,history+5);store.undo();assert.equal(store.getState().designSettings.fontFamily,before.fontFamily);store.redo();assert.equal(store.getState().designSettings.fontFamily,'Georgia, serif');assert.equal(packet.summary().websiteAvailable,true)});

function recommendationFixture(){const store=createStudioStore(seedState),discovery=createDiscoveryStore(store),set=discovery.create();for(const [question,answer] of [['business-summary','Service consultancy'],['audience-primary','Business owners'],['goal-primary','generate-leads'],['action-primary','Book a call'],['required-pages',['home','contact']],['brand-direction',['minimal']],['proof-available','yes']])discovery.respond(set,question,answer);const strategies=createStrategyStore(store,discovery),strategy=strategies.create(set);strategies.draftFromDiscovery(strategy);strategies.edit(strategy,'business.primaryOffering','Advisory services');strategies.edit(strategy,'message.positioning','Clear expert guidance');const library=createLibraryRegistry(),registry=createComponentRegistry();librarySeeds.forEach(item=>library.register(item));componentDefinitions.forEach(item=>registry.register(item));const recommendations=createRecommendationStore({documentStore:store,discoveryStore:discovery,strategyStore:strategies,library,componentRegistry:registry});return{store,discovery,set,strategies,strategy,library,registry,recommendations};}
test('Recommendation generation is deterministic explainable and Website-history free',()=>{const f=recommendationFixture(),before=f.store.exportSnapshot(),history=f.store.getHistory().entries.length,ids=f.recommendations.generate({discoveryResponseSetId:f.set,strategyId:f.strategy}),items=ids.map(id=>f.recommendations.get(id));assert.deepEqual(items.map(item=>item.category),['starter-package','page-template','composition','variant','design-settings']);assert.ok(items.every(item=>item.rationale&&item.evidenceKeys.length&&item.changeScope));assert.equal(items[0].target.libraryItemId,'starter.lead-generation');assert.ok(items.filter(item=>item.target.libraryItemId).every(item=>f.library.resolve(item.target.libraryItemId).status==='certified'));assert.equal(f.store.exportSnapshot(),before);assert.equal(f.store.getHistory().entries.length,history)});
test('Recommendation inspect dismiss and staleness preserve Website state and prior evidence',()=>{const f=recommendationFixture(),ids=f.recommendations.generate({discoveryResponseSetId:f.set,strategyId:f.strategy}),before=f.store.exportSnapshot(),item=f.recommendations.inspect(ids[0]);assert.equal(item.status,'proposed');f.recommendations.dismiss(ids[1],'rally-staff');assert.equal(f.recommendations.get(ids[1]).status,'dismissed');f.strategies.edit(f.strategy,'goals.primary','inform');assert.equal(f.recommendations.get(ids[0]).status,'stale');assert.throws(()=>f.recommendations.apply(ids[0],{confirmReplacement:true}),/Stale recommendation/);assert.equal(f.store.exportSnapshot(),before);assert.equal(f.recommendations.get(ids[1]).dismissedBy.id,'rally-staff')});
test('Library and Design recommendations apply through canonical undoable boundaries',()=>{const f=recommendationFixture(),ids=f.recommendations.generate({discoveryResponseSetId:f.set,strategyId:f.strategy}),pageRecommendation=ids.map(id=>f.recommendations.get(id)).find(item=>item.category==='page-template'),designRecommendation=ids.map(id=>f.recommendations.get(id)).find(item=>item.category==='design-settings'),beforePages=f.store.getState().website.pageIds.length;f.recommendations.apply(pageRecommendation.id);assert.equal(f.store.getState().website.pageIds.length,beforePages+1);assert.equal(f.recommendations.get(pageRecommendation.id).status,'applied');f.store.undo();assert.equal(f.store.getState().website.pageIds.length,beforePages);assert.equal(f.recommendations.get(pageRecommendation.id).status,'applied');f.store.redo();f.recommendations.apply(designRecommendation.id);assert.equal(f.store.getState().designSettings.radius,8);f.store.undo();assert.notEqual(f.store.getState().designSettings.radius,8);f.store.redo();assert.equal(f.store.getState().designSettings.radius,8)});
test('Unavailable recommendation targets fail before Website mutation',()=>{const f=recommendationFixture();f.store.replaceWithBlankWebsite('Blank',true);const before=f.store.exportSnapshot(),ids=f.recommendations.generate({discoveryResponseSetId:f.set,strategyId:f.strategy}),variant=ids.map(id=>f.recommendations.get(id)).find(item=>item.category==='variant');assert.equal(variant.applicable,false);assert.throws(()=>f.recommendations.apply(variant.id),/No Hero/);assert.equal(f.store.exportSnapshot(),before)});
test('Recommendations Packet step and records stay separate from review workflow stores',()=>{const f=recommendationFixture(),comments=createConversationStore(f.store),tasks=createTaskStore(f.store,comments),versions=createReviewVersionStore(f.store),reviews=createReviewSessionStore(f.store,comments,versions),review=reviews.create('Independent'),conversation=comments.create({pageId:'page-home',body:'Note'}),task=tasks.createFromConversation(conversation,{title:'Task'}),packet=createStrategyPacketStore(f.store,f.discovery,f.strategies);packet.open();packet.setStep('recommendations');const history=f.store.getHistory().entries.length;f.recommendations.generate({discoveryResponseSetId:f.set,strategyId:f.strategy});assert.equal(packet.getState().currentStep,'recommendations');assert.equal(f.store.getHistory().entries.length,history);assert.equal(reviews.get(review).status,'draft');assert.equal(comments.get(conversation).status,'open');assert.equal(tasks.get(task).status,'todo');assert.equal(versions.list().length,0)});

test('Stage 6 happy path derives current readiness and applies shared Website changes',()=>{const f=recommendationFixture(),comments=createConversationStore(f.store),versions=createReviewVersionStore(f.store),reviews=createReviewSessionStore(f.store,comments,versions),packet=createStrategyPacketStore(f.store,f.discovery,f.strategies);for(const field of strategyFields.filter(field=>field.required))if(!f.strategies.get(f.strategy).fields[field.key].value)f.strategies.edit(f.strategy,field.key,field.kind==='list'?['focused']:'Resolved decision');let summary=deriveStage6Summary({documentStore:f.store,discoveryStore:f.discovery,strategyStore:f.strategies,recommendationStore:f.recommendations,reviewSessionStore:reviews});assert.equal(summary.nextAction,'recommendations');const ids=f.recommendations.generate({discoveryResponseSetId:f.set,strategyId:f.strategy}),design=ids.map(id=>f.recommendations.get(id)).find(item=>item.category==='design-settings'),page=ids.map(id=>f.recommendations.get(id)).find(item=>item.category==='page-template');f.recommendations.apply(design.id);f.recommendations.apply(page.id);packet.open();for(const step of packet.steps){packet.setStep(step);assert.equal(packet.getState().currentStep,step);}assert.equal(packet.summary().pageCount,f.store.getState().website.pageIds.length);assert.equal(f.store.getState().designSettings.radius,8);summary=deriveStage6Summary({documentStore:f.store,discoveryStore:f.discovery,strategyStore:f.strategies,recommendationStore:f.recommendations,reviewSessionStore:reviews});assert.equal(summary.recommendations,'partially-applied');assert.equal(summary.nextAction,'packet')});

test('Stage 6 staleness is shared and regeneration preserves historical proposals',()=>{const f=recommendationFixture(),comments=createConversationStore(f.store),versions=createReviewVersionStore(f.store),reviews=createReviewSessionStore(f.store,comments,versions),ids=f.recommendations.generate({discoveryResponseSetId:f.set,strategyId:f.strategy}),before=f.store.exportSnapshot();f.strategies.edit(f.strategy,'goals.primary','inform');assert.ok(ids.some(id=>f.recommendations.get(id).status==='stale'));assert.equal(deriveStage6Summary({documentStore:f.store,discoveryStore:f.discovery,strategyStore:f.strategies,recommendationStore:f.recommendations,reviewSessionStore:reviews}).recommendations,'stale');assert.throws(()=>f.recommendations.apply(ids[0],{confirmReplacement:true}),/Stale recommendation/);assert.equal(f.store.exportSnapshot(),before);const regenerated=f.recommendations.generate({discoveryResponseSetId:f.set,strategyId:f.strategy});assert.equal(f.recommendations.list().length,ids.length+regenerated.length);assert.ok(regenerated.every(id=>f.recommendations.get(id).status==='proposed'))});

test('Packet reconciles preview identity across Starter replacement Undo and Redo',()=>{const f=recommendationFixture(),packet=createStrategyPacketStore(f.store,f.discovery,f.strategies),original=f.store.exportSnapshot(),ids=f.recommendations.generate({discoveryResponseSetId:f.set,strategyId:f.strategy}),starter=ids.map(id=>f.recommendations.get(id)).find(item=>item.category==='starter-package');packet.open();packet.setStep('preview');f.recommendations.apply(starter.id,{confirmReplacement:true});let view=packet.getState(),state=f.store.getState();assert.ok(state.pages[view.previewPageId]);assert.equal(view.previewPageId,state.website.pageIds[0]);assert.equal(packet.summary().websiteAvailable,true);f.store.undo();view=packet.getState();state=f.store.getState();assert.equal(f.store.exportSnapshot(),original);assert.ok(state.pages[view.previewPageId]);assert.equal(view.currentStep,'preview');f.store.redo();view=packet.getState();state=f.store.getState();assert.ok(state.pages[view.previewPageId]);assert.equal(packet.summary().pageCount,state.website.pageIds.length)});

test('Stage 6 integration leaves collaboration review task and version state independent',()=>{const f=recommendationFixture(),comments=createConversationStore(f.store),tasks=createTaskStore(f.store,comments),versions=createReviewVersionStore(f.store),reviews=createReviewSessionStore(f.store,comments,versions),review=reviews.create('Integration review'),conversation=comments.create({pageId:'page-home',body:'Keep separate'}),task=tasks.createFromConversation(conversation,{title:'Independent task'}),version=versions.create({label:'Before integration'}),ids=f.recommendations.generate({discoveryResponseSetId:f.set,strategyId:f.strategy}),design=ids.map(id=>f.recommendations.get(id)).find(item=>item.category==='design-settings');f.recommendations.apply(design.id);deriveStage6Summary({documentStore:f.store,discoveryStore:f.discovery,strategyStore:f.strategies,recommendationStore:f.recommendations,reviewSessionStore:reviews});assert.equal(reviews.get(review).status,'draft');assert.equal(comments.get(conversation).status,'open');assert.equal(tasks.get(task).status,'todo');assert.equal(versions.get(version).label,'Before integration')});
